/**
 * DEMONSTRATION DATA AND ITS ANALYSIS for the advanced templates (2026-11-12).
 *
 * The dataset is FICTIONAL and says so (`fictional: true`): respondents are generated by walking the real survey
 * with the population generator, so every row is one the survey can actually produce — screen-outs, routing and
 * all. In the choice exercises the generated respondents choose by a stated preference model (cheaper is better,
 * more is better, plus noise), so that the analyses below have something real to find; the model is returned with
 * the dataset and is not a claim about any market.
 *
 * The analyses are the real ones, run on those rows: best-minus-worst scores for MaxDiff; for conjoint both the
 * counting analysis (how often a level was chosen when shown) and an aggregate multinomial logit fitted by
 * Newton–Raphson, whose part-worths recover the model the choices were generated from. Nothing is a made-up number.
 */
import type { SurveyDefinition, Question } from "@rescript/schema";
import { designRowsFor } from "@rescript/engine";
import { findSurveyTemplate } from "./index.js";
import { generatePopulation } from "./generate.js";
import type { AnswerFn } from "./simulate.js";

type Row = Record<string, unknown>;
const rng = (seed: number) => () => { let t = (seed += 0x6d2b79f5); t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
const gumbel = (u: number) => -Math.log(-Math.log(Math.min(1 - 1e-9, Math.max(1e-9, u))));
const designOf = (def: SurveyDefinition, q: Question) => def.designs.find((d) => d.id === (q.settings as { designRef?: string }).designRef);
const attributesOf = (d: { config?: unknown }) => ((d.config as { attributes?: { name: string; levels: string[] }[] }).attributes ?? []);

/** the part-worth a level has in the demonstration model: price falls with cost, a brand list is flat but for a small first-brand edge, everything else rises level by level */
export function demoPartWorth(attribute: string, levelIndex: number, levels: number): number {
  if (/price|cost/i.test(attribute)) return -1.2 * (levelIndex / Math.max(1, levels - 1));
  if (/brand/i.test(attribute)) return levelIndex === 0 ? 0.3 : 0;
  return 0.8 * (levelIndex / Math.max(1, levels - 1));
}

/** answers for the choice exercises of one survey, chosen by the demonstration model */
export function demoChoiceAnswers(def: SurveyDefinition): Record<string, AnswerFn> {
  const out: Record<string, AnswerFn> = {};
  for (const q of def.questions) {
    const d = designOf(def, q);
    if (!d) continue;
    if (q.type === "conjoint_task") {
      const attrs = attributesOf(d);
      out[q.id] = (_loop, qq, ctx) => {
        const rand = rng(ctx.state.seed * 31 + 7);
        const tasks = new Map<string, { alt: string; u: number }[]>();
        for (const r of designRowsFor(qq, (d.file?.rows ?? []) as Row[], ctx.state.seed, ctx.state.calculated)) {
          const none = Number(r.none_option) === 1;
          const u = none ? 0.4 : attrs.reduce((s, a) => s + demoPartWorth(a.name, a.levels.indexOf(String(r[a.name])), a.levels.length), 0);
          (tasks.get(String(r.task)) ?? tasks.set(String(r.task), []).get(String(r.task))!).push({ alt: String(r.alt), u: u + gumbel(rand()) });
        }
        return Object.fromEntries([...tasks].map(([t, alts]) => [t, alts.reduce((a, b) => (b.u > a.u ? b : a)).alt]));
      };
    } else if (q.type === "maxdiff_task") {
      const n = ((d.config as { items?: string[] }).items ?? []).length;
      out[q.id] = (_loop, qq, ctx) => {
        const rand = rng(ctx.state.seed * 17 + 3);
        const tasks = new Map<string, { idx: string; u: number }[]>();
        for (const r of designRowsFor(qq, (d.file?.rows ?? []) as Row[], ctx.state.seed, ctx.state.calculated)) {
          /* the first items of the list matter most in the demonstration model */
          const u = 2 * (1 - (Number(r.item_index) - 1) / Math.max(1, n - 1)) + gumbel(rand());
          (tasks.get(String(r.task)) ?? tasks.set(String(r.task), []).get(String(r.task))!).push({ idx: String(r.item_index), u });
        }
        return Object.fromEntries([...tasks].map(([t, items]) => { const s = [...items].sort((a, b) => b.u - a.u); return [t, { best: s[0].idx, worst: s[s.length - 1].idx }]; }));
      };
    }
  }
  return out;
}

export interface DemoDataset {
  templateKey: string;
  /** always true: these are generated, fictional respondents — never mixed with collected data */
  fictional: true;
  note: string;
  seed: number;
  requested: number;
  statuses: Record<string, number>;
  /** one row per respondent in export-column form, with STATUS */
  rows: Row[];
}

export function buildDemoDataset(templateKey: string, count = 200, seed = 20261112): DemoDataset {
  const t = findSurveyTemplate(templateKey);
  if (!t) throw new Error(`no template ${templateKey}`);
  const def = t.build(`demo-${templateKey}`);
  const rep = generatePopulation(def, { count, seed, pinned: demoChoiceAnswers(def) });
  const rows = rep.respondents.filter((r) => !r.blocked).map((r) => ({ RESPONDENT: `DEMO-${String(r.index + 1).padStart(4, "0")}`, STATUS: r.endStatus, ...r.vars }));
  const statuses: Record<string, number> = {};
  for (const r of rows) statuses[String(r.STATUS)] = (statuses[String(r.STATUS)] ?? 0) + 1;
  return { templateKey, fictional: true, seed, requested: count, statuses, rows, note: "Fictional demonstration data: generated respondents walking the real survey. In choice exercises they choose by a simple stated model (cheaper and more is better, earlier list items matter more, plus noise). Not collected from anyone, and not a description of any market." };
}

/* ------------------------------------------------------------ analyses */

export interface Frequency { variable: string; label: string; base: number; counts: { code: string; label: string; n: number; pct: number }[] }
/** a single-choice variable's distribution among the rows that have it */
export function frequency(def: SurveyDefinition, rows: Row[], variable: string): Frequency | null {
  const q = def.questions.find((x) => x.variableName === variable);
  if (!q || !q.options.length) return null;
  const have = rows.filter((r) => r[variable] !== undefined && r[variable] !== null && r[variable] !== "");
  return { variable, label: q.text.replace(/<[^>]+>/g, "").slice(0, 120), base: have.length, counts: q.options.map((o) => { const n = have.filter((r) => String(r[variable]) === String(o.code)).length; return { code: String(o.code), label: o.label, n, pct: have.length ? Math.round((1000 * n) / have.length) / 10 : 0 }; }) };
}

export interface MaxDiffScore { item: string; shown: number; best: number; worst: number; /** (best − worst) / shown, −1…1 */ score: number }
/** best-minus-worst counting scores, from the exported task columns (<VAR>_T<n>_BEST / _WORST / _ORDER) */
export function maxdiffScores(def: SurveyDefinition, rows: Row[], variable: string): MaxDiffScore[] {
  const q = def.questions.find((x) => x.variableName === variable && x.type === "maxdiff_task");
  const items = q ? (((designOf(def, q)?.config ?? {}) as { items?: string[] }).items ?? []) : [];
  const tally = items.map((item) => ({ item, shown: 0, best: 0, worst: 0, score: 0 }));
  for (const r of rows) for (let t = 1; r[`${variable}_T${t}_ORDER`] !== undefined; t++) {
    for (const i of String(r[`${variable}_T${t}_ORDER`]).split("|")) if (tally[Number(i) - 1]) tally[Number(i) - 1].shown++;
    const b = tally[Number(r[`${variable}_T${t}_BEST`]) - 1], w = tally[Number(r[`${variable}_T${t}_WORST`]) - 1];
    if (b) b.best++; if (w) w.worst++;
  }
  for (const x of tally) x.score = x.shown ? Math.round((1000 * (x.best - x.worst)) / x.shown) / 1000 : 0;
  return tally.sort((a, b) => b.score - a.score);
}

export interface ConjointLevel { attribute: string; level: string; shown: number; chosen: number; /** chosen / shown */ share: number; /** aggregate logit part-worth, the attribute's first level = 0 */ partWorth: number }
export interface ConjointResult { tasks: number; noneShare: number; levels: ConjointLevel[]; importance: { attribute: string; pct: number }[]; converged: boolean; note: string }

/** the choice sets a row answered: per task, the alternatives' attribute levels and the one chosen */
function choiceSets(def: SurveyDefinition, rows: Row[], variable: string) {
  const q = def.questions.find((x) => x.variableName === variable && x.type === "conjoint_task");
  const d = q ? designOf(def, q) : undefined;
  const attrs = d ? attributesOf(d) : [];
  const sets: { alts: { levels: number[]; none: boolean }[]; chosen: number }[] = [];
  if (!q || !d) return { attrs, sets };
  const byKey = new Map<string, Row[]>();
  for (const r of (d.file?.rows ?? []) as Row[]) { const k = `${r.version}|${r.task}`; (byKey.get(k) ?? byKey.set(k, []).get(k)!).push(r); }
  for (const r of rows) for (let t = 1; r[`${variable}_T${t}`] !== undefined; t++) {
    const alts = (byKey.get(`${r[`${variable}_VERSION`]}|${t}`) ?? []).filter((a) => Number(a.is_holdout) !== 1);
    if (!alts.length) continue;
    const chosen = alts.findIndex((a) => String(a.alt) === String(r[`${variable}_T${t}`]));
    if (chosen < 0) continue;
    sets.push({ chosen, alts: alts.map((a) => ({ none: Number(a.none_option) === 1, levels: attrs.map((at) => at.levels.indexOf(String(a[at.name]))) })) });
  }
  return { attrs, sets };
}

/** counting analysis and an aggregate multinomial logit (Newton–Raphson, a small ridge for stability) on the estimation tasks */
export function conjointAnalysis(def: SurveyDefinition, rows: Row[], variable: string): ConjointResult | null {
  const { attrs, sets } = choiceSets(def, rows, variable);
  if (!sets.length) return null;
  /* parameters: for each attribute its levels after the first, then the "none" constant */
  const offset: number[] = []; let k = 0;
  for (const a of attrs) { offset.push(k); k += a.levels.length - 1; }
  const NONE = k; k += 1;
  const x = (alt: { levels: number[]; none: boolean }): number[] => { const v = new Array<number>(k).fill(0); if (alt.none) { v[NONE] = 1; return v; } alt.levels.forEach((l, i) => { if (l > 0) v[offset[i] + l - 1] = 1; }); return v; };
  const X = sets.map((s) => s.alts.map(x));
  let beta = new Array<number>(k).fill(0), converged = false;
  for (let iter = 0; iter < 40 && !converged; iter++) {
    const g = new Array<number>(k).fill(0), H = Array.from({ length: k }, () => new Array<number>(k).fill(0));
    sets.forEach((s, si) => {
      const u = X[si].map((v) => v.reduce((a, b, j) => a + b * beta[j], 0)); const m = Math.max(...u);
      const e = u.map((z) => Math.exp(z - m)); const tot = e.reduce((a, b) => a + b, 0); const p = e.map((z) => z / tot);
      const mean = new Array<number>(k).fill(0);
      X[si].forEach((v, j) => v.forEach((z, c) => { mean[c] += p[j] * z; }));
      X[si][s.chosen].forEach((z, c) => { g[c] += z - mean[c]; });
      X[si].forEach((v, j) => { for (let a = 0; a < k; a++) if (v[a]) for (let b = 0; b < k; b++) if (v[b]) H[a][b] += p[j]; });
      for (let a = 0; a < k; a++) for (let b = 0; b < k; b++) H[a][b] -= mean[a] * mean[b];
    });
    for (let a = 0; a < k; a++) { H[a][a] += 1e-6; }
    /* solve H step = g */
    const A = H.map((r, i) => [...r, g[i]]);
    for (let c = 0; c < k; c++) { let piv = c; for (let r = c + 1; r < k; r++) if (Math.abs(A[r][c]) > Math.abs(A[piv][c])) piv = r; [A[c], A[piv]] = [A[piv], A[c]]; if (Math.abs(A[c][c]) < 1e-12) continue; for (let r = 0; r < k; r++) if (r !== c) { const f = A[r][c] / A[c][c]; for (let j = c; j <= k; j++) A[r][j] -= f * A[c][j]; } }
    const step = A.map((r, i) => (Math.abs(r[i]) < 1e-12 ? 0 : r[k] / r[i]));
    beta = beta.map((b, i) => b + step[i]);
    converged = Math.max(...step.map(Math.abs)) < 1e-6;
  }
  const levels: ConjointLevel[] = attrs.flatMap((a, i) => a.levels.map((level, l) => {
    let shown = 0, chosen = 0;
    for (const s of sets) s.alts.forEach((alt, j) => { if (!alt.none && alt.levels[i] === l) { shown++; if (s.chosen === j) chosen++; } });
    return { attribute: a.name, level, shown, chosen, share: shown ? Math.round((1000 * chosen) / shown) / 1000 : 0, partWorth: l === 0 ? 0 : Math.round(beta[offset[i] + l - 1] * 1000) / 1000 };
  }));
  const ranges = attrs.map((a) => { const pw = levels.filter((l) => l.attribute === a.name).map((l) => l.partWorth); return Math.max(...pw) - Math.min(...pw); });
  const total = ranges.reduce((a, b) => a + b, 0) || 1;
  return {
    tasks: sets.length, noneShare: Math.round((1000 * sets.filter((s) => s.alts[s.chosen].none).length) / sets.length) / 1000, levels, converged,
    importance: attrs.map((a, i) => ({ attribute: a.name, pct: Math.round((1000 * ranges[i]) / total) / 10 })),
    note: "Aggregate multinomial logit on the estimation tasks (holdouts excluded); part-worths are relative to each attribute's first level. One set of part-worths for the whole sample — for respondent-level utilities and share simulation, estimate with hierarchical Bayes.",
  };
}
